with unpacked as (select id, coupon_codes, ship_to.city as ship_city, size(filter(items, item -> item.qty >= 3)) as bulk_lines, exists(coupon_codes, c -> c like 'W%') as has_welcome_code from carts where array_contains(coupon_codes, 'SPRING10')) select ship_city, round(avg(bulk_lines), 2) as avg_bulk_lines, size(collect_set(ship_city)) as num_ship_cities from unpacked group by ship_city
